def require(ok, message):
    if not ok:
        raise ValueError(message)


def encode(value):
    if isinstance(value, F):
        return str(value)
    if isinstance(value, dict):
        return {str(k): encode(v) for k,v in value.items()}
    if isinstance(value, (tuple,list)):
        return [encode(v) for v in value]
    return value


def module(name, path):
    spec = importlib.util.spec_from_file_location(name, path)
    require(spec is not None and spec.loader is not None, 'Loadable source provider')
    value = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(value)
    return value


def inventory(lp, bridge, wi):
    """Check all moving legacy row meanings, including the four nonzero caps."""
    require(lp.nvars == 875 and len(lp.rows) == 581 and len(lp.equalities) == 16,
            'Complete original218 matrix dimensions')
    face = [v for row in bridge.source_tables(2)[1] for v in row]
    for cell in range(25):
        require(lp.rows[cell] == {16*cell+m:F(1) for m in range(16)}
                and lp.rhs[cell] == face[cell], 'Original raw-node cap')
    for j,group in enumerate(bridge.GROUPS):
        require(lp.rows[25+j] == {16*c+m:F(1) for c in group for m in range(16)}
                and lp.rhs[25+j] == bridge.GROUP_MASSES[j], 'Original raw-group budget')
    require(lp.equalities[4] == {425+k:F(1) for k in range(400)} and lp.erhs[4] == F(53,360)
            and lp.equalities[5] == {k:F(1) for k in range(400)} and lp.erhs[5] == F(1,4),
            'The signed actual survivor and raw mass equalities')
    facecaps = (F(2,125),F(7,270),F(4,375),F(7,810))
    for bit,cap in enumerate(facecaps):
        require(lp.rows[532+bit] == {425+16*c+m:F(1) for c in range(25)
                for m in range(16) if m>>bit&1} and lp.rhs[532+bit] == cap,
                'Every original selected survivor cap')
    coarse,root1,cursor = [],{},536
    for cell in range(25):
        expected = {825+cell:F(1),850+cell:F(1)}
        for m in range(16):
            k = 16*cell+m
            require(lp.rows[132+k] == {425+k:F(1),k:-F(wi[cell],5)}
                    and lp.rhs[132+k] == 0, 'All400 original density links')
            expected[k],expected[425+k] = -F(wi[cell],5),F(1)
        require(lp.rows[cursor] == expected and lp.rhs[cursor] == 0, 'Common coarse deletion link')
        coarse.append(cursor)
        cursor += 1
        if cell >= 10:
            require(lp.rows[cursor] == {825+cell:F(1)} and lp.rhs[cursor] == 0, 'E3 root1-zero row')
            root1[cell] = cursor
            cursor += 1
    require(cursor == 576, 'All25 coarse and15 root1-zero rows')
    q = (Z,F(1,5),F(1,5),F(3,20),F(1,5))
    eta = (F(1,18),)+(F(1,9),)*4
    for s in range(5):
        require(lp.equalities[6+s] == {825+s:F(1),830+s:F(1)} and lp.erhs[6+s] == q[s]/90
                and lp.rows[576+s] == {830+s:-F(1)} and lp.rhs[576+s] == -q[s]/135,
                'Original E3 equality and lower marginal')
    for c in range(5):
        require(lp.equalities[11+c] == {850+5*c+s:F(1) for s in range(5)}
                and lp.erhs[11+c] == eta[c]*(1+int(c>=2))/100, 'Original E5 row total')
    profiles = {start+s for start in (28,78) for s in range(1,5)}
    profiles |= {start+5*c+3 for start in (53,103) for c in range(5)}
    moving = set(range(28)) | profiles | set(range(132,581))
    exact = set(range(28,132))-profiles
    require(not moving&exact and moving|exact == set(range(581)), 'Exhaustive legacy inequality inventory')
    return (coarse,root1), {'inequalities':{'transported':len(moving),'exact':len(exact)},
                          'equalities':{'transported':11,'exact':4,'zero_price':1}}


def survivor_cap_additions(prices, par):
    """Apply125's actual-depth cylinder envelopes without a depth multiplier."""
    b25,b27,b75,b81 = prices
    require(min(prices) >= 0, 'Nonnegative original survivor-cap prices')
    d,k = par['delta'],par['kbar']
    s3 = b27+b81
    source = d*(13*b25/2250+b27/108+b75/375+b81/324+b25/240)
    primitive = (s3,k*s3,b25,b25,s3,k*s3,b25+s3+b75)
    return source,primitive,(s3,k*s3)


def price_record(record, domain, bridge, row_inventory):
    """Direct581/16 specialization of227--230 plus all four selected caps."""
    par = domain['parameters']
    caps,budgets = domain['raw_caps'],domain['raw_budgets']
    d,R,G,kappa = (par[k] for k in ('delta','rho','gap','kbar'))
    y = {int(k):F(v) for k,v in record['nonzero_inequality_duals'].items()}
    z = list(map(F,record['equality_duals']))
    require(len(z)==16 and z[4]==0 and z[5]>=0 and all(0<=i<581 and v>=0 for i,v in y.items()),
            'Measured legacy sign and support conditions')
    get = lambda i:y.get(i,Z)
    coarse,root1 = row_inventory
    alpha,beta = z[6:11],[get(576+s) for s in range(5)]
    gamma = {(c,s):get(root1[5*c+s]) for c in range(2,5) for s in range(5)}
    xi = max([Z]+[beta[s]-alpha[s] for s in range(1,5)])
    chi = max([Z]+[-alpha[s] for s in range(1,5)])
    b0 = max(beta[1:])
    b1 = max([Z]+[gamma[c,s]-alpha[s]+beta[s] for c in range(2,5) for s in range(1,5)])
    b4 = max([Z]+[gamma[c,s]-alpha[s] for c in range(2,5) for s in range(1,5)])
    k = [alpha[s]/90-beta[s]/135 for s in range(5)]
    sg = [max(Z,k[3]),max(Z,k[3]-k[1]),max(Z,k[3]-k[2])]
    pure_source = min(d/4*sum(sg),3*d/(4*(3-2*d))*max(sg))+d*(xi/360+chi/720)
    t = z[11:16]
    a5 = max([Z]+[-v for v in t])
    a15 = max([Z]+[-v for v in t[2:]])
    b15 = max([Z]+t[:2])
    cu = max(-F(1+int(c>=2),100)*t[c] for c in range(1,5))
    five_source = d/18*max(Z,t[0]/100+max(Z,cu))
    atom_prices = [get(132+16*i+m)+get(coarse[i]) for i in range(25) for m in range(16)]
    u = [max(atom_prices[16*i:16*(i+1)]) for i in range(25)]
    primitive = [10*max(Z,k[3]-k[4]),Z,xi+max((par['Cbar']-1)*b0,par['tbar']*b1),
                 chi+par['tbar']*b4,a5,a15+(kappa-1)*(a15+b15),max(u)]
    cap_prices = [get(i) for i in range(532,536)]
    cap_source,cap_primitive,qprices = survivor_cap_additions(cap_prices,par)
    primitive = [a+b for a,b in zip(primitive,cap_primitive)]
    profiles = [d/450*max(get(start+s) for s in range(1,5)) for start in (28,78)]
    profiles += [max(par['v0' if c<2 else 'v1']*get(start+5*c+3) for c in range(5))/den
                 for start,den in ((53,27),(103,81))]
    source = pure_source+five_source+cap_source+sum(profiles)
    base = [get(i)+get(25+(0 if i<5 else 1 if i<10 else 2))+z[5] for i in range(25)]
    face = [v for r in bridge.source_tables(2)[1] for v in r]
    subtraction = sum(get(i)*face[i] for i in range(25))
    subtraction += sum(get(25+j)*v for j,v in enumerate(bridge.GROUP_MASSES))+z[5]/4
    vertices,witnesses = [],[]
    for q5,q15 in ((Z,Z),(R/G,Z),(Z,R/G)):
        co = [base[i]+u[i]*(d/5*int(i//5!=0)+q5*int(i%5==4)+q15*int(i//5>=2 and i%5==4)) for i in range(25)]
        val,witness = bridge.lp_bound(co,caps,budgets)
        shift = G*(qprices[0]*q5+qprices[1]*q15)
        vertices.append({'q':[q5,q15],'signed_raw_transport':val-subtraction,'survivor_cap_wrong_slot_upper':shift})
        witnesses.append(witness)
    return {'combined_source_upper':source,'E3_source_upper':pure_source,'E5_source_upper':five_source,
            'survivor_cap_prices_25_27_75_81':cap_prices,'survivor_cap_source_upper':cap_source,
            'survivor_cap_primitive_prices':list(cap_primitive),'survivor_cap_wrong_slot_coefficients':list(qprices),
            'old_profile_source_uppers_25_75_27_81':profiles,'raw_base_prices':base,
            'raw_face_subtraction':subtraction,'raw_mass_price':z[5],
            'primitive_prices':dict(zip(PRIMITIVES,primitive)),'common_raw_node_prices':u,
            'common_atom_fields_sha256':sha256(json.dumps(encode(atom_prices),separators=(',',':')).encode()).hexdigest(),
            'triangle_vertices':vertices},witnesses


def compile_tail(par, coefficients, cut, tail):
    """Remove exactly25,27,75,81;125 and135 remain in the infinite tail."""
    require(type(cut) is int and cut>=5, 'Fixed complete-series cut')
    a = {int(t):F(v) for t,v in coefficients.items() if F(v)}
    require(a and all(1<=t<=8 and v>0 for t,v in a.items()), 'Original positive hinge coefficients')
    w0,w4 = a.get(1,Z),sum(v for t,v in a.items() if t>=2)
    d,kappa = par['delta'],par['kbar']
    c,h = tail.envelopes(d)
    ell,m,b = [],[],[]
    for j,p in enumerate((3,5,5,5)):
        plain = tail.geometric_support(p,(3,2,2,2)[j],cut)
        punctured = tail.geometric_support(p,(5,3,3,2)[j],cut)
        for out,i in ((ell,0),(m,1),(b,2)):
            out.append(w0*plain[i]+w4*punctured[i])
    m3,m5,_,_ = m
    source = sum(x*y+hh*z for x,y,hh,z in zip(c,ell,h,b))+d*m5/240
    source += (w0+w4)*(F(1,72)+F(2669,88200)+23*d/5880)
    primitive = (m3,kappa*m3,m5,m5,m3,kappa*m3,sum(m))
    face = w0*(F(163,1800)+F(2669,88200))+w4*(F(19,648)+F(2669,88200))
    require(sum(x*y for x,y in zip(tail.envelopes(Z)[0],ell))+(w0+w4)*(F(1,72)+F(2669,88200))==face,
            'Exact face-tail recovery with only four original punctures')
    return {'cut':cut,'weights':[w0,w4],'geometric_coefficients':ell,'finite_error_counts':m,
            'infinite_continuations':b,'combined_source_upper':source,'primitive_prices':dict(zip(PRIMITIVES,primitive)),
            'wrong_slot_coefficients':[m3,kappa*m3],'face_tail':face,
            'retained_original_labels':[25,27,75,81]}


def joined_error(row, par, tail):
    R,G = par['rho'],par['gap']
    prices = [F(row['primitive_prices'][k])+F(tail['primitive_prices'][k]) for k in PRIMITIVES]
    source = F(row['combined_source_upper'])+F(tail['combined_source_upper'])-F(tail['face_tail'])
    qcoeff = list(map(F,tail['wrong_slot_coefficients']))
    vertices = []
    for vertex in row['triangle_vertices']:
        q5,q15 = map(F,vertex['q'])
        residual = R-G*(q5+q15)
        require(residual>=0, 'One nonnegative shared residual budget')
        value = source+F(vertex['signed_raw_transport'])+F(vertex['survivor_cap_wrong_slot_upper'])
        value += G*(qcoeff[0]*q5+qcoeff[1]*q15)+residual*max(prices)
        vertices.append({'q':[q5,q15],'row_and_tail_minus_face_tail_upper':value})
    return {'combined_primitive_prices':dict(zip(PRIMITIVES,prices)), 'triangle_vertices':vertices,
            'transport_error_upper':max(v['row_and_tail_minus_face_tail_upper'] for v in vertices)}


def original_tests(doc):
    require(doc['r']==doc['rho']=='0' and F(doc['mass'])==F(53,360), 'Original face domain and actual mass')
    require(doc['linear_indices']==[1,2,7,10,17,18,23,26,32,33,36], 'All eleven original affine tails')
    rows = [(f"AP11-{r['block']}",r) for r in doc['AP11_block_results']]
    rows += [('AP13',doc['AP13_result'])]
    rows += [(f"linear-{r['index']}",r) for r in doc['linear_results']]
    require(len(rows)==16 and [r['block'] for r in doc['AP11_block_results']]==list(range(4)), 'All sixteen independent tests')
    out = {}
    for name,original in rows:
        scan = original['scan']
        require(scan['pruning_credit']=='whole-hinge-deletion' and F(original.get('at_one',0))==0,
                'Full D_H pruning and zero constant term for each transported test')
        M = F(scan['complete_hinge_upper'])
        previous = F(original.get('previous_upper',original.get('previous_cost_upper')))
        require(M<previous, 'The source scan wins its external face-only previous-bound minimum')
        counts,classes = scan['counts'],{}
        require(counts['prefix_available']==counts['prefix_bounded']==0
                and F(scan['maximum_pruned_uppers']['prefix'])==-1, 'No legacy prefix candidate was used')
        require(counts['two']==125000 and counts['four']==50*(counts['two']-counts['two_bounded'])
                and counts['six']==10*(counts['four']-counts['four_bounded'])
                and counts['joint']-1==counts['six']-counts['six_bounded'], 'Complete original branch partition')
        for kind,mult in (('two',500),('four',10),('six',1)):
            n,upper = counts[kind+'_bounded'],F(scan['maximum_pruned_uppers'][kind])
            require(n>0 and 0<=upper<=M, 'Nonempty original accepted-minimum pruning class')
            classes[kind] = {'pruned_nodes':n,'original_leaves':mult*n,'face_upper':upper,'face_margin':M-upper}
        require(sum(r['original_leaves'] for r in classes.values())+counts['joint']-1
                ==scan['covered_containing_choices']==62500000, 'Every original leaf accounted exactly once')
        a = {int(t):F(v) for t,v in scan['coefficients'].items() if F(v)}
        require(a and all(1<=t<=8 and v>0 for t,v in a.items()), 'Source-bound original hinge coefficients')
        out[name] = {'original_coefficients':a,'face_complete_hinge_upper':M,'previous_face_bound':previous,
                     'previous_minus_scan_face_margin':previous-M,'classes':classes,'source_counts':counts,
                     'branch_decisions_sha256':scan['branch_decisions_sha256'],
                     'face_tail':F(scan['maximizing_witness']['complete_tail_constant'])}
    return out


def join_complete_head(test, candidate_errors):
    """Transport accepted minima, including expanded leaves, before maximizing."""
    errors = [F(candidate_errors[str(j)]['error_upper']) for j in (2,4,6)]
    joint = max(Z,F(test['joint_transport_error_upper']))
    comparisons = {}
    for k,(kind,count) in enumerate((('two',1),('four',2),('six',3))):
        error = max(errors[:count])
        face = F(test['classes'][kind]['face_upper'])
        comparisons[kind] = {'face_upper':face,'transport_error_upper':error,'complete_upper':face+error,
                             'face_margin_after_transport':F(test['face_complete_hinge_upper'])-face-error}
    expanded_error = max(joint,*errors)
    expanded_upper = F(test['face_complete_hinge_upper'])+expanded_error
    complete = max(expanded_upper,*(r['complete_upper'] for r in comparisons.values()))
    return {'pruning_candidate_errors':candidate_errors,'pruning_class_bounds':comparisons,
            'joint_transport_allowance':joint,'expanded_accepted_minimum_error':expanded_error,
            'expanded_accepted_minimum_upper':expanded_upper,'complete_hinge_upper':complete,
            'additive_complete_allowance':complete-F(test['face_complete_hinge_upper']),
            'covered_containing_choices':62500000,
            'previous_bound_scope':'The previous bound is recorded only at the face. The transported scan is valid directly; no untransported previous minimum, whole-load majorant or integer-identity feedback is used.'}


def independent_specializations(base, bank, domain, bridge, lp, wi, inv, prices):
    """Compare representative zero-cap legacy rows with independent229/230 APIs."""
    load = lambda n:module('legacy_compare_'+n,module('named_artifact_io', base/'certificate_io.py').named_artifact(base/'frontier', n+'.py'))
    old,e5,partial,complete,exact,pair = [load(n) for n in ('joint_deletion_row_transport',
        'selected_deletion_mask_row_transport','retained_pair_row_transport','complete_retained_row_transport',
        'retained135_heavy_comparison','retained135125_heavy_comparison')]
    pre,_,_,descendant = bridge.source_tables(2)
    oldlp = exact.lp_class(base)(lp,wi,pre,'nested')
    newlp = pair.lp_class(base)(lp,wi,pre,descendant,'nested')
    e5.check_row_meanings(oldlp,wi)
    oldinv,addedinv = old.row_inventory(oldlp,wi),partial.new_inventory(newlp,pre,descendant,wi)
    require(oldinv==inv and newlp.rows[:581]==lp.rows and newlp.rhs[:581]==lp.rhs
            and newlp.equalities[:16]==lp.equalities and newlp.erhs[:16]==lp.erhs,
            'Legacy581/16 system is the exact unchanged complete-matrix prefix')
    selected = {min(bank),max(bank)}
    selected |= {max(bank,key=lambda k:F(bank[k]['nonzero_inequality_duals'].get(str(i),'0'))) for i in range(532,536)}
    selected |= {max(bank,key=lambda k:F(bank[k]['equality_duals'][5]))}
    selected |= {k for k in prices}
    records = []
    par,caps,budgets = domain['parameters'],domain['raw_caps'],domain['raw_budgets']
    for key in sorted(selected):
        source = bank[key]
        cleared = {**source,'nonzero_inequality_duals':{i:v for i,v in source['nonzero_inequality_duals'].items() if not 532<=int(i)<=535}}
        padded = {**cleared,'equality_duals':source['equality_duals']+['0']*40}
        inherited,_ = partial.price_record(padded,par,caps,budgets,bridge,old,e5,oldinv,addedinv)
        reference,_ = complete.price_record(padded,inherited,par,caps,budgets,bridge)
        direct,_ = price_record(cleared,domain,bridge,inv)
        for field in ('combined_source_upper','old_profile_source_uppers_25_75_27_81','raw_base_prices',
                      'raw_face_subtraction','raw_mass_price','primitive_prices','common_raw_node_prices'):
            require(direct[field]==reference[field], 'Independent229/230 specialization '+field)
        require([(v['q'],v['signed_raw_transport']) for v in direct['triangle_vertices']]
                ==[(v['q'],v['signed_raw_transport']) for v in reference['triangle_vertices']], 'Independent common raw support')
        full,_ = price_record(source,domain,bridge,inv)
        cap_source,cap_primitive,qcoeff = survivor_cap_additions(full['survivor_cap_prices_25_27_75_81'],par)
        require(full['combined_source_upper']==direct['combined_source_upper']+cap_source
                and all(full['primitive_prices'][n]==direct['primitive_prices'][n]+cap_primitive[i] for i,n in enumerate(PRIMITIVES)),
                'The only additional legacy motion is the four selected caps')
        records.append({'dual_key':key,'survivor_cap_prices':full['survivor_cap_prices_25_27_75_81'],
                        'source_addition':cap_source,'primitive_addition':cap_primitive,'wrong_slot_coefficients':qcoeff})
    return {'zero_padded_legacy_rows':len(records),'comparisons':records,
            'unchanged_prefix_inequalities':581,'unchanged_prefix_equalities':16}


def calculate(base, delta=DEFAULT_D, rho=DEFAULT_R, gap=DEFAULT_G, cut=DEFAULT_CUT):
    io = module('legacy_io',base/'certificate_io.py')
    read = lambda p:json.loads(io.read_artifact_bytes(base/p))
    doc = read('certificates/source_norms/retained-transport/retained_deletion_survival_comparison.json')
    pins = dict(PINS)
    for path,pin in doc['source_sha256'].items():
        require(path not in pins or pins[path]==pin, 'Consistent original source '+path)
        pins[path] = pin
    for path,pin in pins.items():
        require(sha256(io.read_artifact_bytes(base/path)).hexdigest()==pin, 'Pinned logical source '+path)
    load = lambda n:module('legacy_'+n,io.named_artifact(base/'frontier', n+'.py'))
    small,tail,pruning,codec,old,bridge,depth,raw_provider,lp_provider = [load(n) for n in (
        'retained_small_domain_all_bank_transport','retained_punctured_tail_support','uniform_pruning_candidate_transport',
        'retained_pair_row_transport','retained_deletion_survival_comparison','k_face_common_seven_hinges',
        'second_depth_seven_comparison','joint_selected_source_comparison','retained_deletion_heavy_comparison')]
    domain = small.parameters(delta,rho,gap)
    par = domain['parameters']
    require(par['gap']<=F(53,2700), 'Common domain of the general pruning233 formulas')
    tests = original_tests(doc)
    supports = {name:compile_tail(par,t['original_coefficients'],cut,tail) for name,t in tests.items()}
    require(all(t['face_tail']==supports[name]['face_tail'] for name,t in tests.items()), 'Every original face tail is removed exactly once')
    wi = [int(5*w) for row in bridge.source_tables(2)[2] for w in row]
    lp = lp_provider.RetainedDeletionLP(raw_provider.RawSelectedLP(bridge),wi)
    require(lp.specification()==doc['raw_lp'], 'Exact source-bound original matrix')
    inv,inventory_counts = inventory(lp,bridge,wi)
    bank = old.decode_dual_bank(doc['rational_duals'])
    require(len(bank)==16391, 'The complete original218 bank')
    for name,t in tests.items():
        t['fixed_tail_support'] = supports[name]
        t['joint_transport_error_upper'] = None
        t['maximizing_rows'] = []
    records,digest,probe_digest = {},sha256(),sha256()
    nonzero_caps,positive_mass = 0,0
    for number,(key,dual) in enumerate(sorted(bank.items()),1):
        row,witnesses = price_record(dual,domain,bridge,inv)
        records[key] = row
        nonzero_caps += any(row['survivor_cap_prices_25_27_75_81'])
        positive_mass += row['raw_mass_price']>0
        digest.update(json.dumps(encode([key,row]),sort_keys=True,separators=(',',':')).encode())
        probe = [key,row['combined_source_upper'],list(row['primitive_prices'].values()),
                 [(v['q'][0],v['q'][1],v['signed_raw_transport'],v['survivor_cap_wrong_slot_upper']) for v in row['triangle_vertices']]]
        probe_digest.update(json.dumps(encode(probe),separators=(',',':')).encode())
        for name,t in tests.items():
            joined = joined_error(row,par,supports[name])
            value = joined['transport_error_upper']
            if t['joint_transport_error_upper'] is None or value>t['joint_transport_error_upper']:
                t['joint_transport_error_upper'] = value
                t['maximizing_rows'] = [key]
                t['maximizing_witness'] = {'dual_key':key,'complete_row_record':row,'row_and_tail':joined,'raw_primal_dual_witnesses':witnesses}
            elif value==t['joint_transport_error_upper']:
                t['maximizing_rows'].append(key)
        if number%2000==0:
            print(str(number)+'/16391 legacy rows; sixteen independently source-bound tail consumers.',flush=True)
    require(nonzero_caps==8483, 'Every nonzero original survivor-cap price retained')
    selected_maxima = {t['maximizing_witness']['dual_key'] for t in tests.values()}
    checks = independent_specializations(base,bank,domain,bridge,lp,wi,inv,selected_maxima)
    encoded = codec.encode_price_bank(records)
    require(codec.decode_price_bank(encoded)==encode(records), 'Lossless complete legacy price-bank transport')
    for name,t in tests.items():
        a = t['original_coefficients']
        candidate_errors = {str(j):pruning.evaluate_with_finite(a,j,pruning.finite_coefficients(a,j,bridge,depth),
                            par['delta'],par['rho'],par['gap'],cut) for j in (2,4,6)}
        t.update(join_complete_head(t,candidate_errors))
    return encode({'schema':'erdos7-legacy-retained-complete-head-transport-v1','source_sha256':pins,'domain':domain,
        'original_matrix':doc['raw_lp'],'constraint_inventory':inventory_counts,'dual_count':len(bank),
        'nonzero_survivor_cap_price_rows':nonzero_caps,'positive_raw_mass_price_rows':positive_mass,
        'direct_raw_support_optimizations':3*len(bank),'row_tail_joins':16*len(bank),
        'complete_price_records_sha256':digest.hexdigest(),'compact_price_records_sha256':probe_digest.hexdigest(),
        'encoded_price_bank':encoded,'independent_specializations':checks,'tests':tests,
        'objective_key_partition':'Only transport errors are maximized across the whole16391-row bank. Each raw dual upper stays attached to its original218 objective and branch; unrelated raw RHS values are never compared.',
        'scope':'Sixteen source-bound original218 complete heads on the certified positive source rectangle, with all original coefficient vectors, every two/four/six/joint accepted minimum, zero prefix uses, and every complete infinite tail. Prior face-only minima, integer-identity feedback, other52-cost terms, signed actual-mass/count-tail assembly, K comparison, actual-family attainment, Lean verification and unrestricted Erdos7 remain separate.'})


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--base',type=Path,default=Path(__file__).resolve().parents[2])
    parser.add_argument('--delta',default=str(DEFAULT_D));parser.add_argument('--rho',default=str(DEFAULT_R))
    parser.add_argument('--gap',default=str(DEFAULT_G));parser.add_argument('--cut',type=int,default=DEFAULT_CUT)
    modes = parser.add_mutually_exclusive_group()
    modes.add_argument('--write',action='store_true');modes.add_argument('--check',action='store_true')
    args = parser.parse_args()
    result = calculate(args.base,args.delta,args.rho,args.gap,args.cut)
    io = module('legacy_output',args.base/'certificate_io.py')
    if args.write:
        io.write_certificate_text(args.base/CERTIFICATE,json.dumps(result,indent=2)+'\n')
    else:
        require(result==json.loads(io.read_artifact_bytes(args.base/CERTIFICATE)), 'Exact complete legacy-head transport certificate')
    for name,t in result['tests'].items():
        print(name+': complete upper='+str(float(F(t['complete_hinge_upper'])))+', allowance='+str(float(F(t['additive_complete_allowance']))))
    print('PASS:16391 legacy duals,8483 active survivor-cap rows and all16 complete original heads;52-cost/K assembly remains separate.')


if __name__=='__main__':
    try:
        main()
    except(ValueError,ArithmeticError,OSError,KeyError,TypeError,json.JSONDecodeError) as error:
        print('FAIL: '+str(error),file=sys.stderr)
        raise SystemExit(1)
